document.addEventListener('click',e=>{const series=e.target.closest('[data-dota-series]');if(series){const m=sportDotaSeriesItems[Number(series.dataset.dotaSeries)];if(m)tvDotaStreams(m);return;}const local=e.target.closest('[data-sport-local]');if(local){const c=sportLocalChannels[Number(local.dataset.sportLocal)];if(c)tvPlay(c);return;}if(e.target.closest('[data-sportworld]')){go('tvworld',{sport:true});return;}const tab=e.target.closest('[data-sporttab]');if(tab){sportTab=tab.dataset.sporttab;if(sportTab==='esports'&&sportMode==='followed')sportMode='all';show({name:'sport'},{scroll:0,focus:'sporttab:'+sportTab});return;}const csMatch=e.target.closest('[data-csmatch]');if(csMatch){const list=sportCsMatches.filter(x=>sportMode!=='live'||x.live),m=list[Number(csMatch.dataset.csmatch)];if(m)tvDotaStreams(m,'cs2');return;}const ds=e.target.closest('[data-dotastream]');if(ds){const x=sportDotaStreams[Number(ds.dataset.dotastream)];if(x)playTwitchNative(x);return;}const cs=e.target.closest('[data-csstream]');if(cs){const x=sportCsItems[Number(cs.dataset.csstream)];if(x)playTwitchNative(x);return;}const dt=e.target.closest('[data-dota]');if(dt){const x=sportDotaItems[Number(dt.dataset.dota)];if(x)tvDotaStreams(x);return;}const l=e.target.closest('[data-lol]');if(l){tvValorantStreams('lol:'+l.dataset.lol,l);return;}const v=e.target.closest('[data-valorant]');if(v){tvValorantStreams(v.dataset.valorant,v);return;}const vk=e.target.closest('[data-sportvk]');if(vk){const x=sportVkItems[Number(vk.dataset.sportvk)];if(x)playVkTitle({id:'vk:'+x.id,name:x.title,type:4,poster:x.image},[],null,null,x);return;}const reminder=e.target.closest('[data-sport-reminder-remove]');if(reminder){const item=sportActiveReminders()[Number(reminder.dataset.sportReminderRemove)];if(item){sportRemoveReminder(item);show({name:'sport'},{focus:'sport:followed'});}return;}const unfollow=e.target.closest('[data-sport-unfollow]');if(unfollow){const item=sportActiveFollows()[Number(unfollow.dataset.sportUnfollow)];if(item){sportToggleFollow(item.kind,item.league,item.name,item.teamId);show({name:'sport'},{focus:'sport:followed'});}return;}const panel=e.target.closest('[data-sportpanel]');if(panel){show({name:'sport',panel:panel.dataset.sportpanel});return;}const mode=e.target.closest('[data-sportmode]');if(mode){sportMode=mode.dataset.sportmode;show({name:'sport'},{scroll:0,focus:'sport:'+sportMode});return;}if(e.target.closest('[data-sportrefresh]')){show({name:'sport',refresh:true});return;}const card=e.target.closest('[data-sportitem]');if(card){const x=sportItems[Number(card.dataset.sportitem)];if(x)playTrailerNative({...x,sport:true});}});

