const tvSportScoreText = score => score === '' || score == null ? '—' : String(score);
function sportUpdateOpenScore(match){const dialog=document.querySelector('[data-sport-event-id]');if(!dialog||dialog.dataset.sportEventId!==String(match.id))return;const score=dialog.querySelector('.sport-event-score'),state=dialog.querySelector('.sport-event-state');if(score)score.innerHTML=match.state==='pre'?'<span>VS</span>':'<strong>'+esc(tvSportScoreText(match.home.score))+'</strong><i>:</i><strong>'+esc(tvSportScoreText(match.away.score))+'</strong>';if(state){state.classList.toggle('live',match.state==='in');state.textContent=match.state==='in'?'● ИДЁТ МАТЧ':match.state==='post'?'ЗАВЕРШЁН':new Date(match.date).toLocaleString('ru-RU',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'});}}
function sportListingNames(match,data){
  if(!data||!Array.isArray(data.events)||!match?.home?.name||!match?.away?.name)return [];
  const made=Date.parse(data.made||''),when=Date.parse(match.date||'');if(!Number.isFinite(made)||Math.abs(Date.now()-made)>48*3600000||!Number.isFinite(when))return [];
  const norm=x=>String(x||'').normalize('NFKD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/ё/g,'е').replace(/[^\p{L}\p{N}]+/gu,' ').trim();
  const parts=x=>norm(x).split(' ').filter(w=>w.length>=3&&!['club','football','basketball','hockey','team'].includes(w));
  const eq=(a,b)=>{const x=parts(a),y=parts(b);return !!(x.length&&y.length&&x.some(w=>w.length>=4&&y.includes(w))&&(x.every(w=>y.includes(w))||y.every(w=>x.includes(w))));};
  const leagueSports={'НБА':['basketball'],'НХЛ':['ice hockey','hockey'],'РПЛ':['soccer','football'],'АПЛ':['soccer','football'],'Лига чемпионов':['soccer','football'],'Ла Лига':['soccer','football'],'НФЛ':['american football'],'МЛБ':['baseball']},expected=leagueSports[match.league]||[];const out=new Map();for(const e of data.events){const kind=norm(e.s||'');if(expected.length&&kind&&!expected.includes(kind))continue;const t=Date.parse(e.t||'');if(!Number.isFinite(t)||Math.abs(when-t)>90*60000)continue;const sides=String(e.n||'').split(/\s+(?:vs\.?|v\.?|@|at)\s+/i);if(sides.length!==2||!((eq(match.home.name,sides[0])&&eq(match.away.name,sides[1]))||(eq(match.home.name,sides[1])&&eq(match.away.name,sides[0]))))continue;for(const [region,names] of Object.entries(e.c||{}))if(Array.isArray(names))for(const name of names)if(typeof name==='string'&&name.trim()){const item={name:name.trim(),region:String(region||'').trim()};out.set(norm(item.name)+'|'+norm(item.region),item);}}return [...out.values()];
}
function sportChannelKey(s){return String(s||'').normalize('NFKD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/\b(?:hd|fhd|uhd|4k|sd)\b/g,' ').replace(/[^\p{L}\p{N}]+/gu,' ').trim().replace(/\s+/g,' ');}
function sportNetworkMatches(channel,network){
 const aliases={netherlands:'nl',nederland:'nl',nl:'nl',serbia:'rs',rs:'rs',slovenia:'si',si:'si',greece:'gr',gr:'gr',czechia:'cz',czech:'cz',cz:'cz',turkey:'tr',turkiye:'tr',tr:'tr',bulgaria:'bg',bg:'bg',latvia:'lv',lv:'lv',france:'fr',fr:'fr',germany:'de',de:'de',italy:'it',it:'it',spain:'es',es:'es',portugal:'pt',pt:'pt',romania:'ro',ro:'ro',hungary:'hu',hu:'hu',slovakia:'sk',sk:'sk',ukraine:'ua',ua:'ua',poland:'pl',polska:'pl',pl:'pl',canada:'ca',ca:'ca',usa:'us',us:'us','united states':'us',uk:'gb',gb:'gb','united kingdom':'gb',ireland:'ie',ie:'ie',croatia:'hr',hr:'hr',lithuania:'lt',lt:'lt',israel:'il',il:'il',nz:'nz',russia:'ru',ru:'ru',australia:'au',au:'au',brazil:'br',brasil:'br',br:'br'};
 const region=x=>aliases[sportChannelKey(x)]||'';
 const parse=value=>{const a=sportChannelKey(value).split(' ');let r=region(a[a.length-1]);if(r)a.pop();return {raw:sportChannelKey(value),base:a.join(''),region:r};};
 const a=parse(channel?.name),b=parse(typeof network==='string'?network:network?.name),wanted=region(typeof network==='object'?network?.region:'')||b.region,actual=a.region||region(channel?.cc);
 if(!a.raw||!b.raw||a.base!==b.base)return false;if(wanted&&actual&&wanted!==actual)return false;
 return !b.region||!actual||actual===b.region;
}
