window.lumaYoutubeSearchResolved=(id,html)=>{const done=tvYoutubeSearchPending.get(id);if(done){tvYoutubeSearchPending.delete(id);done(html?{html}:{error:true});}};
function tvYoutubeLiveSearch(query){return new Promise(resolve=>{if(!NATIVE?.searchYoutubeLive){resolve({error:true});return;}const id=++tvYoutubeSearchSeq;const timer=setTimeout(()=>{tvYoutubeSearchPending.delete(id);resolve({error:true});},30000);tvYoutubeSearchPending.set(id,value=>{clearTimeout(timer);resolve(value);});NATIVE.searchYoutubeLive(query,id);});}
async function tvDotaStreams(match,kind='dota'){const returnKey=document.activeElement?.dataset?.k||'';dlg('<div class="sport-eyebrow">КИБЕРСПОРТ · DOTA 2</div><h3>'+esc(match.home)+' — '+esc(match.away)+'</h3><p class="sub" id="valorantStreamStatus">Ищем эфиры Twitch и YouTube по названиям команд…</p><div class="cmenu valorant-stream-list" id="valorantStreams"></div><button class="btn f" tabindex="-1" data-valorant-close="1" data-k="val:close">Закрыть</button>');$('#modal').dataset.returnSport=returnKey;if(kind==='cs2'){const label=$('#modal .sport-eyebrow');if(label)label.textContent='КИБЕРСПОРТ · CS2';}const expectedStatus=$('#valorantStreamStatus');const citoPromise=kind==='cs2'&&match.live?fetch(tvPx('https://cito.gg/','','',true),{signal:AbortSignal.timeout(10000)}).then(async r=>r.ok?{html:await r.text()}:{error:true}).catch(()=>({error:true})):Promise.resolve({});const youtubePromise=tvYoutubeLiveSearch(match.home+' '+match.away+(kind==='cs2'?' CS2 live':' Dota 2 live'));const searches=await Promise.all([...new Set([match.home,match.away,...esportsTeamKeys(match.home),...esportsTeamKeys(match.away),match.home+' '+match.away,kind==='cs2'?'Counter-Strike':'Dota 2'].filter(x=>String(x||'').trim().length>=3))].map(tvTwitchSearch));const [ytResult,citoResult]=await Promise.all([youtubePromise,citoPromise]);if(ytResult.html&&!/ytInitialData\s*=/.test(ytResult.html))ytResult.error=true;const result=[...new Map(searches.flat().map(x=>[x.id,x])).values()];if(!expectedStatus?.isConnected||$('#valorantStreamStatus')!==expectedStatus||!$('#valorantStreams'))return;const norm=s=>String(s||'').normalize('NFKD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^\p{L}\p{N}]+/gu,' ').trim(),a=norm(match.home),b=norm(match.away);tvValorantStreamItems=result.filter(x=>(kind==='cs2'?/counter.strike/i.test(x.game)&&!esportsOffTopic(x.title):/dota 2/i.test(x.game))&&esportsTeamsInMatchTitle(x.title,match.home,match.away)&&!/\b(?:rerun|replay|highlights|reprise)\b|повтор|запись|нарезк|разбор/i.test(x.title)).map(x=>({...x,provider:'twitch'})).slice(0,12);$('#valorantStreamStatus').textContent=tvValorantStreamItems.length?'Возможные эфиры по названию команд. Проверьте перед просмотром.':searches.some(x=>x.error)?'Поиск Twitch выполнен не полностью. Попробуйте позже.':'Совпадений по названиям обеих команд сейчас нет.';const citoLinks=kind==='dota'&&match.id?.startsWith('spectate:')?(match.broadcasts||[]):esportsCitoStreams(citoResult.html||'',match),liveYoutube=esportsYoutubeLiveResults(ytResult.html||''),liveTwitch=await Promise.all(citoLinks.filter(x=>x.provider==='twitch').slice(0,10).map(x=>tvTwitchSearch(x.id).catch(()=>[])));if(!expectedStatus?.isConnected||$('#valorantStreamStatus')!==expectedStatus)return;const confirmed=citoLinks.filter(x=>x.provider==='youtube'?liveYoutube.some(y=>y.id===x.id):liveTwitch.some(r=>r.some(y=>String(y.id).toLowerCase()===x.id.toLowerCase()&&(kind==='cs2'?/counter.strike/i:/dota 2/i).test(y.game))));if(confirmed.length){tvValorantStreamItems=confirmed.concat(tvValorantStreamItems.filter(x=>!confirmed.some(y=>y.provider==='twitch'&&y.id.toLowerCase()===String(x.id).toLowerCase())));$('#valorantStreamStatus').textContent='Трансляции матча по данным '+(kind==='cs2'?'Cito':'Spectate Esports')+'. Совпадения по названию показаны отдельно.';}else if(kind==='cs2'&&citoResult.error)$('#valorantStreamStatus').textContent+=' Источник ссылок временно недоступен.';{const youtube=esportsYoutubeLiveResults(ytResult.html||'').filter(x=>esportsTeamsInMatchTitle(x.title,match.home,match.away)&&(kind==='cs2'?!esportsOffTopic(x.title):/\bdota\s*2\b|дота\s*2/i.test(x.title))&&!/\b(?:rerun|replay|highlights)\b|повтор|запись|нарезк/i.test(x.title));tvValorantStreamItems.push(...youtube.filter(x=>!confirmed.some(y=>y.provider==='youtube'&&y.id===x.id)));if(ytResult.error)$('#valorantStreamStatus').textContent+=' Поиск YouTube недоступен.';else if(youtube.length&&!confirmed.length)$('#valorantStreamStatus').textContent='Возможные эфиры по названию команд. Источник расписания не подтвердил ссылки.';}$('#valorantStreams').innerHTML=tvValorantStreamItems.map((x,i)=>`<button class="btn f" tabindex="-1" data-valorant-stream="${i}" data-k="val:stream:${i}"><span class="val-platform ${x.provider}">${x.provider==='youtube'?'<svg viewBox="0 0 24 24" aria-hidden="true"><rect x="1" y="4" width="22" height="16" rx="5" fill="currentColor"/><path d="M10 8.4v7.2l6-3.6z" fill="#d82742"/></svg>':'<svg viewBox="0 0 24 24" aria-hidden="true"><path fill="currentColor" d="M4.4 2 3 5.8v13.3h4.6V22h2.6l2.9-2.9h3.7l4.2-4.2V2H4.4Zm14.8 12-2.8 2.8h-4.5L9.4 19v-2.2H5.7V3.6h13.5V14Zm-3.1-7.5h-1.5v4.9h1.5V6.5Zm-4.2 0h-1.5v4.9h1.5V6.5Z"/></svg>'}</span><span class="val-channel"><b>${esc(x.name)}</b><small>${esc((x.confirmed?'':'Возможный эфир · ')+x.title)}</small></span><span class="val-arrow">›</span></button>`).join('');}

let tvYoutubePending='',tvYoutubeRoute=null;
function tvPlayYoutubeStream(id){if(!/^[\w-]{11}$/.test(id))return;tvYoutubePending=id;tvYoutubeRoute=route;if(NATIVE?.prepareYoutubeEmbed)NATIVE.prepareYoutubeEmbed(id);else NATIVE?.openYoutube(id);}
window.lumaYoutubeEmbedReady=(id,ok)=>{if(id!==tvYoutubePending)return;if(route!==tvYoutubeRoute){tvYoutubePending='';tvYoutubeRoute=null;if(ok)NATIVE?.clearYoutubeEmbed?.();return;}tvYoutubePending='';tvYoutubeRoute=null;if(!ok){NATIVE?.openYoutube(id);return;}openTrailerWeb({src:'YouTube',id,url:'https://www.youtube-nocookie.com/embed/'+id+'?autoplay=1&playsinline=1&rel=0'});};
